// learnInitOnce gates runLearnInitOnce so the seed pass happens at
// most once per CLI process. The sync.Once keeps the cost off the
// hot path for repeat command invocations within an MCP session.
var learnInitOnce sync.Once

// runLearnInitOnce opens the canonical store path, fires initLearn
// once per process, and downgrades any failure to a stderr warning.
// Per the self-learning loop's soft-validation contract, a seed
// failure must never abort the CLI — the recall path returns the
// empty envelope if entity_lookups is missing rows, which is the
// same behavior an opt-out CLI sees.
func runLearnInitOnce(ctx context.Context) {
	learnInitOnce.Do(func() {
		dbPath := defaultDBPath("uber-jobs-pp-cli")
		s, err := store.OpenWithContext(ctx, dbPath)
		if err != nil {
			fmt.Fprintf(os.Stderr, "warning: uber-jobs-pp-cli: learn init: open store: %v\n", err)
			return
		}
		defer s.Close()
		if err := initLearn(ctx, s.DB()); err != nil {
			fmt.Fprintf(os.Stderr, "warning: uber-jobs-pp-cli: learn init: %v\n", err)
		}
	})
}

// learnCommonIdentityFields is the ordered, domain-neutral list
// ResourceEntitiesFromJSON walks when a resource has no more specific
// identity key. Missing JSON keys are skipped, so one list can serve
// every collection.
var learnCommonIdentityFields = []string{
	"name", "title", "display_name", "full_name", "short_name", "label",
	"slug", "key", "code", "id", "address",
}

// learnResourceTypeFields returns the per-resource identity-field map
// passed to Recall so entity_match can be exact when the stored JSON
// actually carries the identity.
func learnResourceTypeFields() map[string][]string {
	return map[string][]string{
		"careers": {"name", "title", "display_name", "full_name", "short_name", "label", "slug", "key", "code", "id", "address"},
	}
}

// learnIdentityFieldsFor returns the identity fields for one resource
// type, falling back to the common list when the type is unknown.
func learnIdentityFieldsFor(resourceType string) []string {
	if fields, ok := learnResourceTypeFields()[resourceType]; ok && len(fields) > 0 {
		return fields
	}
	return append([]string(nil), learnCommonIdentityFields...)
}
